def solution() -> int:
    # Given strings
    S = "zy"
    T = "bc"

    # Create a DP table with dimensions (len(S)+1) x (len(T)+1)
    m, n = len(S), len(T)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if S[i - 1] == T[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The result is stored in dp[m][n]
    return dp[m][n]

