def solution():
    items = [(1, 3), (3, 4), (6, 2), (5, 1), (2, 4), (2, 5)]
    capacity = 30
    n = len(items)
    total_weight = sum(item[0] for item in items)
    if total_weight <= capacity:
        selected = list(range(n))
        total_value = sum(item[1] for item in items)
        return True, total_value, selected
    else:
        dp = [[0] * (capacity + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            weight_i, value_i = items[i - 1]
            for w in range(capacity + 1):
                if weight_i <= w:
                    dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weight_i] + value_i)
                else:
                    dp[i][w] = dp[i - 1][w]
        total_value = dp[n][capacity]
        selected_items = []
        w = capacity
        for i in range(n, 0, -1):
            if dp[i][w] != dp[i - 1][w]:
                selected_items.append(i - 1)
                w -= items[i - 1][0]
        selected_items.sort()
        return True, total_value, selected_items

