def solution() -> int:
    # Given sorted array
    arr = [3, 4, 10, 11, 21]
    target = 4

    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    # Target not found (though present in this case)
    return -1

